def is_nested(string):
    depth = 0
    max_depth = 0
    balanced = True
    for ch in string:
        if ch == '[':
            depth += 1
            max_depth = max(max_depth, depth)
        elif ch == ']':
            depth -= 1
            if depth < 0:
                balanced = False
    if depth != 0:
        balanced = False
    return balanced and max_depth >= 2
